        tya
        and #$0f
        sta music_volume
        ldx music_cur_voice
        inx
        stx music_filter_voice
        jmp music_process_commands
; Commands $AC-$AF: bit0 selects the short or long note length table (music_length_table_sel).
music_cmd_length_table
        tya
        and #$01
        sta music_length_table_sel
        jmp music_process_commands
; Command $An: $A0-$A3 waveform (triangle, saw, pulse, noise), $A4-$A6 articulation and its ADSR, $A7/$A8 tie on/off, $A9/$AA ring modulation on/off, $AB pulse+triangle, $AC-$AF length table.
music_cmd_misc
        cpy #$ac
        bcs music_cmd_length_table
        lda #$51
        cpy #$ab
        beq l_e645
        tya
        and #$0f
        cmp #$04
        bcs music_cmd_articulation
        tax
        lda music_waveforms,x
l_e645
        ldx music_cur_voice
        sta music_ctrl_v1,x
        jmp music_process_commands
music_cmd_articulation
        cmp #$07
        bcs music_cmd_tie
        and #$03
        ldx music_cur_voice
        sta music_articulation,x
        tay
        dey
        php
        lda music_adsr_set_offsets,x
        tay
        plp
        bmi l_e681
        beq l_e677
        lda music_adsr_sets+4,y
        pha
        lda music_adsr_sets+5,y
l_e66d
        sta music_sr,x
        pla
        sta music_ad,x
        jmp music_process_commands
l_e677
; not executed $e677-$e680
        lda music_adsr_sets+2,y
        pha
        lda music_adsr_sets+3,y
        jmp l_e66d
l_e681
        lda music_adsr_sets,y
        pha
        lda music_adsr_sets+1,y
        jmp l_e66d
music_adsr_set_offsets
        !byte $00,$06,$0c               ; offset of each voice in music_adsr_sets
music_cmd_tie
        cmp #$09
        bcs music_cmd_ring_mod
        and #$01
        ldx music_cur_voice
        sta music_tie_v1,x
music_cmd_done
        jmp music_process_commands
music_cmd_ring_mod
; not executed $e69d-$e6b4
        and #$01
        asl
        asl
        sta music_temp
        ldx music_cur_voice
        lda music_ctrl_v1,x
        and #$fb
        ora music_temp
        sta music_ctrl_v1,x
        jmp music_cmd_done
l_e6b5
        rts
; A = length index, Y = articulation: returns X = gate-on ticks and Y = negative release ticks from music_length_table (7/8, 1/2 or full-1 split).
music_calc_note_ticks
        ldx music_length_table_sel
        beq l_e6be
        clc
        adc #$10
l_e6be
        tax
        dey
        beq l_e6e9
        bmi l_e6cc
        lda music_length_table,x
        tax
        ldy #$ff
        dex
        rts
l_e6cc
        lda music_length_table,x
        lsr
        lsr
        lsr
        bne l_e6d6
        lda #$01
l_e6d6
        sta music_temp
        lda music_length_table,x
        sec
        sbc music_temp
        tax
        lda #$00
        sec
        sbc music_temp
        tay
        rts
l_e6e9
; not executed $e6e9-$e6f8
        lda music_length_table,x
        lsr
        sta music_temp
        tax
        lda #$00
        sec
        sbc music_temp
        tay
        rts
; Note lengths in ticks: 16 entries for the short table, 16 for the long table (music_length_table_sel = 1).
music_length_table
        !byte $20,$10,$08,$04,$02,$01,$08,$08,$30,$18,$0c,$06,$03,$02,$08,$08
        !byte $40,$20,$10,$08,$04,$02,$08,$08,$60,$30,$18,$0c,$06,$04,$08,$08
sid_voice_offsets
        !byte $00,$07,$0e               ; SID register offset of voices 1-3
music_waveforms
        !byte $11,$21,$41,$81           ; control bytes $11 triangle, $21 saw, $41 pulse, $81 noise
; Command $Bn: copies the 6 AD/SR bytes of instrument n from music_instruments into the voice's music_adsr_sets.
music_cmd_instrument
        tya
        and #$07
        asl
        asl
        asl
        tay
        ldx #$00
        lda music_cur_voice
        beq l_e740
        lsr
        bcs l_e74f
l_e731
        lda music_instruments,y
        sta music_adsr_sets+$c,x
        iny
        inx
        cpx #$06
        bne l_e731
        jmp music_cmd_done
l_e740
        lda music_instruments,y
        sta music_adsr_sets,x
        iny
        inx
        cpx #$06
        bne l_e740
        jmp music_cmd_done
l_e74f
        lda music_instruments,y
        sta music_adsr_sets+6,x
        iny
        inx
        cpx #$06
        bne l_e74f
        jmp music_cmd_done
; Command $C0 lo hi: writes the two following bytes to the voice's pulse width registers.
music_cmd_pulse_width
        jsr music_read_byte
        ldx music_cur_voice
        ldy sid_voice_offsets,x
        sta PWLO1,y
        jsr music_read_byte
        ldx music_cur_voice
        ldy sid_voice_offsets,x
        sta PWHI1,y
        jmp music_cmd_done
; Command $Dn xx: filter preset n sets cutoff, filter mode and resonance (preset ORed with xx); the next note of this voice writes $D418/$D417.
music_cmd_filter
; not executed $e779-$e7b1
        tya
        and #$07
        asl
        asl
        clc
        adc #$40
        tay
        lda music_instruments,y
        sta CUTLO
        iny
        lda music_instruments,y
        sta CUTHI
        iny
        lda music_instruments,y
        pha
        iny
        lda music_instruments,y
        sta music_filter_mode
        ldx music_cur_voice
        inx
        stx music_filter_voice
        jsr music_read_byte
        sta music_temp
        pla
        ora music_temp
        sta music_filter_reson
        jmp music_cmd_done
; Command $E0 nn: sets music_tempo and the tempo counter to nn frames per tick.
music_cmd_tempo
        jsr music_read_byte
        sta music_tempo
        sta music_tempo_counter
        jmp music_cmd_done
        !byte $ea,$b7,$25,$3e,$ae,$26,$25,$3e
        !byte $ae,$26,$27,$3e,$ae,$26,$27,$3e
        !byte $ae,$26,$3e,$d7,$b7,$57,$3e,$d7
        !byte $b7,$57,$3e,$d7,$b7,$57,$3e,$d7
        !byte $b7,$57,$25,$3e,$ae,$26,$25,$3e
        !byte $ae,$26,$25,$3e,$ae,$26,$25,$3e
        !byte $ae,$26,$3e,$d7,$b7,$57,$3e,$d7
        !byte $b7,$57,$3e,$d7,$b7,$57,$3e,$d7
        !byte $b7,$57,$6a,$40,$7d,$41,$31,$42
        !byte $ad,$42,$90,$44
